        assertEquals("1", appVersion.getBuildNumber());
    }

    @Test
    public void getCommitTest() {
        AppVersion appVersion = AppVersion.parseName("app-1.0.0-h1.build1-abcdef");
        assertEquals("abcdef", appVersion.getCommit());
    }

